CREATE TABLE runtime_targets (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  provider varchar(32) NOT NULL,
  endpoint varchar(512) NOT NULL,
  display_name varchar(128) NOT NULL,
  endpoint_label varchar(512) NOT NULL,
  connection_kind varchar(32) NOT NULL,
  capabilities_json jsonb NOT NULL DEFAULT '[]'::jsonb,
  availability boolean NOT NULL DEFAULT false,
  last_error varchar(512) NOT NULL DEFAULT '',
  checked_at timestamptz NULL,
  system_managed boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT NOW(), created_by bigint NOT NULL DEFAULT 0,
  updated_at timestamptz NOT NULL DEFAULT NOW(), updated_by bigint NOT NULL DEFAULT 0,
  deleted_at bigint NOT NULL DEFAULT 0, deleted_by bigint NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX uq_runtime_targets_live_provider_endpoint ON runtime_targets (provider, endpoint) WHERE deleted_at = 0;
CREATE INDEX idx_runtime_targets_list ON runtime_targets (deleted_at, provider, availability, checked_at DESC);
COMMENT ON TABLE runtime_targets IS '运行目标连接与能力探测事实表';
COMMENT ON COLUMN runtime_targets.id IS '运行目标记录主键'; COMMENT ON COLUMN runtime_targets.provider IS '运行时提供方稳定标识'; COMMENT ON COLUMN runtime_targets.endpoint IS '归一化连接端点标识，不含认证秘密'; COMMENT ON COLUMN runtime_targets.display_name IS '运行目标展示名称'; COMMENT ON COLUMN runtime_targets.endpoint_label IS '已脱敏的端点展示文本'; COMMENT ON COLUMN runtime_targets.connection_kind IS '连接方式，例如 Unix 套接字'; COMMENT ON COLUMN runtime_targets.capabilities_json IS '探测到的运行时能力稳定标识列表'; COMMENT ON COLUMN runtime_targets.availability IS '最近一次探测是否可连接'; COMMENT ON COLUMN runtime_targets.last_error IS '最近探测失败的脱敏诊断摘要'; COMMENT ON COLUMN runtime_targets.checked_at IS '最近完成探测的时间'; COMMENT ON COLUMN runtime_targets.system_managed IS '是否由系统自动发现并维护'; COMMENT ON COLUMN runtime_targets.created_at IS '记录创建时间'; COMMENT ON COLUMN runtime_targets.created_by IS '创建人用户标识，系统为零'; COMMENT ON COLUMN runtime_targets.updated_at IS '最近更新时间'; COMMENT ON COLUMN runtime_targets.updated_by IS '最后更新人用户标识，系统为零'; COMMENT ON COLUMN runtime_targets.deleted_at IS '软删除时间戳，零表示存活'; COMMENT ON COLUMN runtime_targets.deleted_by IS '软删除操作者标识，零表示未删除';
